// Pairs each damage entry with the insured item it refers to. An item can only
// be damaged once per incident, so entries CONSUME the items they match: two
// sword damages need two insured swords. A damage with nothing left to match is
// a claim on something MHPCO never insured, which voids the whole claim.
const damagedItemsFor = (damages: Damage[], insuredItems: Item[]): Item[] => {
  const unclaimed = [...insuredItems];
  return damages.map((damage) => {
    const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
    if (index === -1) {
      throw new Error(`Claim damages a ${damage.itemType} beyond what this policy covers`);
    }
    return unclaimed.splice(index, 1)[0];
  });
};

